package site.cadera.arunika.dungeon.paper;

import java.util.*;
import java.util.function.Consumer;
import org.bukkit.*;
import org.bukkit.entity.Player;
import org.bukkit.event.*;
import org.bukkit.event.inventory.*;
import org.bukkit.event.player.PlayerQuitEvent;
import org.bukkit.inventory.*;
import net.kyori.adventure.text.Component;
import site.cadera.arunika.dungeon.battle.BattlePlan.*;
import site.cadera.arunika.dungeon.core.SessionRegistry.Mode;

/** Native inventory UI; no chat listener or repeating task. All edits recheck authorization. */
final class PaperAdmin implements Listener,AutoCloseable {
 private final ArunikaDungeonPlugin plugin;
 private final Map<UUID,Draft> drafts=new HashMap<>();
 private static final class Menu implements InventoryHolder {
  final UUID owner; boolean clickPending; final Map<Integer,Consumer<Player>> actions=new HashMap<>(); Inventory inv;
  Menu(UUID owner){this.owner=owner;} public Inventory getInventory(){return inv;}
 }
 private static final class Draft {
  final String floor,id;final Mode mode;Point first,second,spawn,boss,exit;final List<Point> mobs=new ArrayList<>();
  Draft(String floor,String id,Mode mode){this.floor=floor;this.id=id;this.mode=mode;}
  Arena arena(){if(first==null||second==null||spawn==null||boss==null||exit==null||mobs.isEmpty()||!first.world().equals(second.world()))throw new IllegalStateException("Set both corners, player, boss, minion(s) and exit");return new Arena(id,mode,new Bounds(new Point(first.world(),Math.min(first.x(),second.x()),Math.min(first.y(),second.y()),Math.min(first.z(),second.z())),new Point(first.world(),Math.max(first.x(),second.x()),Math.max(first.y(),second.y()),Math.max(first.z(),second.z()))),spawn,mobs,boss,exit);}
 }
 PaperAdmin(ArunikaDungeonPlugin plugin){this.plugin=plugin;Bukkit.getPluginManager().registerEvents(this,plugin);}
 private Menu menu(Player p,String title){Menu h=new Menu(p.getUniqueId());h.inv=Bukkit.createInventory(h,54,Component.text(title));return h;}
 private void button(Menu h,int slot,Material m,String name,Consumer<Player> action,String... lines){ItemStack item=new ItemStack(m);var meta=item.getItemMeta();meta.displayName(GuiTheme.name(name,m));if(lines.length>0)meta.lore(Arrays.stream(lines).map(GuiTheme::lore).toList());item.setItemMeta(meta);h.inv.setItem(slot,item);if(action!=null)h.actions.put(slot,action);}
 private void show(Player p,Menu h){for(int slot=45;slot<54;slot++)if(h.inv.getItem(slot)==null)button(h,slot,Material.BLACK_STAINED_GLASS_PANE," ",null);p.openInventory(h.inv);}
 private void cmd(Player p,String command){p.closeInventory();p.performCommand(command);}
 void home(Player p,int page){Menu h=menu(p,"Arunika | Dungeon Admin");var floors=plugin.floors();int last=Math.max(0,(floors.size()-1)/45);int current=Math.max(0,Math.min(page,last));for(int i=current*45;i<Math.min(floors.size(),current*45+45);i++){var f=floors.get(i);button(h,i%45,Material.PAPER,"Floor "+f.number()+" — "+f.name(),q->floor(q,f.id()),"ID: "+f.id(),"Click to manage");}button(h,45,Material.ARROW,"Previous",q->home(q,current-1));button(h,47,Material.COMPASS,"Live sessions",q->monitor(q,0));button(h,49,Material.CHEST,"Exchange editor",q->exchange(q,0));button(h,51,Material.REDSTONE,"Diagnostics",q->cmd(q,"adg diagnostics"));button(h,53,Material.ARROW,"Next",q->home(q,current+1));show(p,h);}
 void floor(Player p,String id){var f=plugin.floors().stream().filter(x->x.id().equals(id)).findFirst().orElseThrow();Menu h=menu(p,"Admin | "+f.name());button(h,10,Material.COMPASS,"Arena setup",q->arenaSelect(q,id));button(h,12,Material.IRON_SWORD,"Wave editor",q->waves(q,id));button(h,14,Material.WITHER_SKELETON_SKULL,"Boss editor",q->{q.closeInventory();q.sendMessage("Current Mythic ID: "+f.bossReference());q.sendMessage("/adg setup boss "+id+" <MythicMobs-ID>");});button(h,29,Material.EMERALD,"Shared drop editor",q->stages(q,id,"shared"));button(h,33,Material.AMETHYST_SHARD,"Private drop editor",q->stages(q,id,"private"));button(h,46,Material.LIME_CONCRETE,"Enable battle configuration",q->confirm(q,"Enable "+id,x->cmd(x,"adg setup enable "+id),x->floor(x,id)));button(h,48,Material.RED_CONCRETE,"Disable battle configuration",q->confirm(q,"Disable "+id,x->cmd(x,"adg setup disable "+id),x->floor(x,id)));button(h,53,Material.ARROW,"Back",q->home(q,0));show(p,h);}
 private void confirm(Player p,String label,Consumer<Player> yes,Consumer<Player> no){Menu h=menu(p,"Confirm | "+label);button(h,20,Material.LIME_CONCRETE,"Confirm",yes);button(h,24,Material.RED_CONCRETE,"Cancel",no);show(p,h);}
 private void arenaSelect(Player p,String floor){Menu h=menu(p,"Arena setup | "+floor);button(h,11,Material.EMERALD,"New/edit shared_1",q->begin(q,floor,"shared_1",Mode.SHARED));button(h,15,Material.AMETHYST_SHARD,"New/edit private_1",q->begin(q,floor,"private_1",Mode.PRIVATE));button(h,22,Material.COMPASS,"Resume draft",q->resume(q));button(h,31,Material.BOOK,"Other arena IDs",q->{q.closeInventory();q.sendMessage("/adg setup arena "+floor+" <arena-id> <shared|private>");});button(h,53,Material.ARROW,"Back",q->floor(q,floor));show(p,h);}
 void begin(Player p,String floor,String id,Mode mode){if(!id.matches("[a-z][a-z0-9_-]{0,47}")||plugin.floors().stream().noneMatch(f->f.id().equals(floor)))throw new IllegalArgumentException("Invalid floor/arena ID");drafts.put(p.getUniqueId(),new Draft(floor,id,mode));resume(p);}
 private void capture(Player p,Draft d,Consumer<Point> set){set.accept(PaperBattlePort.point(p.getLocation()));p.closeInventory();p.sendMessage("Position captured. Move to next point, then /adg setup resume");}
 void resume(Player p){Draft d=drafts.get(p.getUniqueId());if(d==null){p.sendMessage("No arena draft");return;}Menu h=menu(p,"Arena | "+d.id);button(h,10,Material.STICK,"Corner A",q->capture(q,d,x->d.first=x),String.valueOf(d.first));button(h,12,Material.STICK,"Corner B",q->capture(q,d,x->d.second=x),String.valueOf(d.second));button(h,14,Material.ENDER_PEARL,"Player spawn",q->capture(q,d,x->d.spawn=x),String.valueOf(d.spawn));button(h,16,Material.SPAWNER,"Add minion spawn",q->capture(q,d,x->{if(d.mobs.size()>=64)throw new IllegalStateException("64 spawn points max");d.mobs.add(x);}),d.mobs.size()+" points");button(h,23,Material.WITHER_SKELETON_SKULL,"Boss spawn",q->capture(q,d,x->d.boss=x),String.valueOf(d.boss));button(h,25,Material.OAK_DOOR,"Exit / hub",q->capture(q,d,x->d.exit=x),String.valueOf(d.exit));button(h,30,Material.BARRIER,"Clear minion points",q->{d.mobs.clear();resume(q);});button(h,49,Material.LIME_CONCRETE,"Validate and save",q->{Arena a=d.arena();q.closeInventory();plugin.adminEdit(q,d.floor,"arena",null,0,0,a);});button(h,53,Material.ARROW,"Back (keep draft)",q->floor(q,d.floor));show(p,h);}
 private int waveCount(String id){return plugin.adminSnapshot().lootPlans().get(id+":shared").waves().size();}
 private void waves(Player p,String id){Menu h=menu(p,"Wave editor | "+id);int n=waveCount(id);for(int i=1;i<=n;i++){int w=i;button(h,i-1,Material.IRON_SWORD,"Wave "+i,q->{q.closeInventory();q.sendMessage("Replace: /adg setup wave "+id+" "+w+" <Mythic-ID> <amount>");q.sendMessage("Append: /adg setup append-wave "+id+" "+w+" <Mythic-ID> <amount>");});}button(h,45,Material.RED_DYE,"Remove last active wave",q->confirm(q,"Wave count "+Math.max(1,n-1),x->cmd(x,"adg setup count "+id+" "+Math.max(1,n-1)),x->waves(x,id)));button(h,47,Material.LIME_DYE,"Add wave",q->confirm(q,"Wave count "+Math.min(30,n+1),x->cmd(x,"adg setup count "+id+" "+Math.min(30,n+1)),x->waves(x,id)));button(h,53,Material.ARROW,"Back",q->floor(q,id));show(p,h);}
 private void stages(Player p,String floor,String mode){Menu h=menu(p,"Drops | "+mode+" "+floor);int n=waveCount(floor);for(int i=1;i<=n;i++){String stage="wave-"+i;button(h,i-1,Material.IRON_SWORD,"Wave "+i,q->drop(q,floor,mode,stage,100,1,1));}button(h,40,Material.WITHER_SKELETON_SKULL,"Boss drops",q->drop(q,floor,mode,"boss",100,1,1));button(h,53,Material.ARROW,"Back",q->floor(q,floor));show(p,h);}
 private void drop(Player p,String floor,String mode,String stage,int chance,int min,int max){Menu h=menu(p,"Drop | "+stage+" "+mode);var plan=plugin.adminSnapshot().lootPlans().get(floor+":"+mode);var table=stage.equals("boss")?plan.boss():plan.waves().get(Integer.parseInt(stage.substring(5)));button(h,4,Material.BOOK,"Existing entries: "+table.entries().size(),null,"Trigger: "+table.trigger(),"Use /adg loot list and YAML keys to remove/edit");button(h,10,Material.RED_DYE,"Chance -5%",q->drop(q,floor,mode,stage,Math.max(0,chance-5),min,max));button(h,11,Material.PAPER,"Chance: "+chance+"%",null);button(h,12,Material.LIME_DYE,"Chance +5%",q->drop(q,floor,mode,stage,Math.min(100,chance+5),min,max));button(h,19,Material.RED_DYE,"Min -1",q->drop(q,floor,mode,stage,chance,Math.max(1,min-1),max));button(h,20,Material.PAPER,"Minimum: "+min,null);button(h,21,Material.LIME_DYE,"Min +1",q->drop(q,floor,mode,stage,chance,Math.min(max,min+1),max));button(h,28,Material.RED_DYE,"Max -1",q->drop(q,floor,mode,stage,chance,min,Math.max(min,max-1)));button(h,29,Material.PAPER,"Maximum: "+max,null);button(h,30,Material.LIME_DYE,"Max +1",q->drop(q,floor,mode,stage,chance,min,Math.min(4096,max+1)));button(h,40,Material.CHEST,"Add held item",q->confirm(q,"Add held reward",x->cmd(x,"adg loot addhand "+floor+" "+mode+" "+stage+" gui_"+UUID.randomUUID().toString().replace("-","")+" "+chance+" "+min+" "+max),x->drop(x,floor,mode,stage,chance,min,max)),"Hold the reward in main hand before opening GUI");button(h,53,Material.ARROW,"Back",q->stages(q,floor,mode));show(p,h);}
 private void exchange(Player p,int page){Menu h=menu(p,"Admin | Exchange editor");var list=plugin.adminExchangeRewards();int current=Math.max(0,Math.min(page,Math.max(0,(list.size()-1)/45)));for(int i=current*45;i<Math.min(list.size(),current*45+45);i++){var r=list.get(i);button(h,i%45,Material.GOLD_INGOT,r.key(),q->exchangeReward(q,r.key(),r.cost(),r.enabled()),"Cost: "+r.cost(),"Category: "+r.category());}button(h,45,Material.ARROW,"Previous",q->exchange(q,current-1));button(h,47,Material.CHEST,"Add held item",q->exchangeAdd(q,50));button(h,49,Material.BOOK,"Exchange status",q->cmd(q,"adg exchange admin status"));button(h,51,Material.ARROW,"Next",q->exchange(q,current+1));button(h,53,Material.BARRIER,"Back",q->home(q,0));show(p,h);}
 private void exchangeAdd(Player p,int cost){Menu h=menu(p,"New Exchange reward");button(h,20,Material.RED_DYE,"Cost -10",q->exchangeAdd(q,Math.max(1,cost-10)));button(h,22,Material.GOLD_INGOT,"Cost: "+cost,null);button(h,24,Material.LIME_DYE,"Cost +10",q->exchangeAdd(q,Math.min(1000000,cost+10)));button(h,40,Material.CHEST,"Add held item",q->confirm(q,"Add exchange reward",x->cmd(x,"adg exchange admin addhand gui_"+UUID.randomUUID().toString().replace("-","")+" "+cost+" Items"),x->exchangeAdd(x,cost)));button(h,53,Material.ARROW,"Back",q->exchange(q,0));show(p,h);}
 private void exchangeReward(Player p,String key,int cost,boolean enabled){Menu h=menu(p,"Exchange | "+key);button(h,20,Material.RED_DYE,"Cost -10",q->exchangeReward(q,key,Math.max(1,cost-10),enabled));button(h,22,Material.GOLD_INGOT,"Cost: "+cost,null);button(h,24,Material.LIME_DYE,"Cost +10",q->exchangeReward(q,key,Math.min(1000000,cost+10),enabled));button(h,38,Material.LIME_CONCRETE,"Save cost",q->confirm(q,"Set cost "+cost,x->cmd(x,key.equals("universal-ticket")?"adg exchange admin ticket "+cost+" "+(enabled?"on":"off"):"adg exchange admin cost "+key+" "+cost),x->exchangeReward(x,key,cost,enabled)));button(h,42,Material.REDSTONE,enabled?"Disable reward":"Enable reward",q->confirm(q,"Toggle "+key,x->cmd(x,key.equals("universal-ticket")?"adg exchange admin ticket "+cost+" "+(!enabled?"on":"off"):"adg exchange admin enable "+key+" "+!enabled),x->exchangeReward(x,key,cost,enabled)));button(h,53,Material.ARROW,"Back",q->exchange(q,0));show(p,h);}
 private void monitor(Player p,int page){Menu h=menu(p,"Dungeon | Live sessions");var views=plugin.gatewayBattles();int current=Math.max(0,Math.min(page,Math.max(0,(views.size()-1)/45)));for(int i=current*45;i<Math.min(views.size(),current*45+45);i++){var v=views.get(i);button(h,i%45,Material.COMPASS,v.floor()+" / "+v.phase(),q->confirm(q,"Stop session",x->cmd(x,"adg preview stop "+v.id()),x->monitor(x,current)),v.id().toString(),"Arena: "+v.arena()+" | Wave: "+v.wave(),"Alive mobs: "+v.alive()+" | Pending: "+v.pending(),"Remaining: "+v.remainingSeconds()+"s");}button(h,45,Material.ARROW,"Previous",q->monitor(q,current-1));button(h,49,Material.CLOCK,"Refresh",q->monitor(q,current));button(h,51,Material.ARROW,"Next",q->monitor(q,current+1));button(h,53,Material.BARRIER,"Back",q->home(q,0));show(p,h);}
 @EventHandler(priority=EventPriority.HIGHEST) public void click(InventoryClickEvent e){if(!(e.getView().getTopInventory().getHolder() instanceof Menu h))return;boolean alreadyCancelled=e.isCancelled();e.setCancelled(true);if(alreadyCancelled)return;if(!(e.getWhoClicked() instanceof Player p)||!p.getUniqueId().equals(h.owner)||!p.hasPermission("arunika.dungeon.admin")||e.getRawSlot()<0||e.getRawSlot()>=h.inv.getSize()||e.getClick()!=ClickType.LEFT&&e.getClick()!=ClickType.RIGHT)return;var action=h.actions.get(e.getRawSlot());if(action==null||h.clickPending)return;h.clickPending=true;Bukkit.getScheduler().runTask(plugin,()->{h.clickPending=false;if(!p.isOnline()||!p.hasPermission("arunika.dungeon.admin")||p.getOpenInventory().getTopInventory().getHolder()!=h)return;try{action.accept(p);}catch(RuntimeException ex){p.sendMessage("Admin editor: "+ex.getMessage());}});}
 @EventHandler(priority=EventPriority.HIGHEST) public void drag(InventoryDragEvent e){if(e.getView().getTopInventory().getHolder() instanceof Menu)e.setCancelled(true);}
 @EventHandler public void quit(PlayerQuitEvent e){drafts.remove(e.getPlayer().getUniqueId());}
 @Override public void close(){HandlerList.unregisterAll(this);drafts.clear();for(Player p:Bukkit.getOnlinePlayers())if(p.getOpenInventory().getTopInventory().getHolder() instanceof Menu)p.closeInventory();}
}
